#include "Compiler/physical_project_graph_json.h"

#include <inttypes.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static void diag(FisicsSemanticProjectDiagnostic* d,const char* fmt,...){if(!d||d->message[0])return;va_list args;va_start(args,fmt);vsnprintf(d->message,sizeof(d->message),fmt,args);va_end(args);}
static bool js(FILE* out,const char* value){if(fputc('"',out)==EOF)return false;for(const unsigned char* p=(const unsigned char*)(value?value:"");*p;++p){switch(*p){case'"':if(fputs("\\\"",out)==EOF)return false;break;case'\\':if(fputs("\\\\",out)==EOF)return false;break;case'\n':if(fputs("\\n",out)==EOF)return false;break;case'\r':if(fputs("\\r",out)==EOF)return false;break;case'\t':if(fputs("\\t",out)==EOF)return false;break;default:if(*p<0x20u){if(fprintf(out,"\\u%04x",(unsigned)*p)<0)return false;}else if(fputc(*p,out)==EOF)return false;}}return fputc('"',out)!=EOF;}
static bool nullable(FILE* out,const char* value){return value?js(out,value):fputs("null",out)!=EOF;}
static const char* subject_name(FisicsPhysicalSubjectKind k){return k==FISICS_PHYSICAL_SUBJECT_SEMANTIC_ID?"semantic_id":"source_identity";}
static const char* policy_name(FisicsPhysicalUnitPolicy p){return p==FISICS_PHYSICAL_UNIT_DIMENSION_ONLY?"dimension_only":p==FISICS_PHYSICAL_UNIT_EXACT?"exact_unit":"convertible_unit";}
static const char* state_name(FisicsPhysicalContractState s){return s==FISICS_PHYSICAL_STATE_SOURCE_COMPATIBLE?"source_compatible":s==FISICS_PHYSICAL_STATE_SOURCE_UNVERIFIED?"source_unverified":"external_declared";}

static bool write_receipt(FILE* out,const FisicsPhysicalSourceReceipt* r,bool final){return fputs("    {\n      \"artifact_path\": ",out)!=EOF&&js(out,r->artifact_path)&&fputs(",\n      \"source\": {\n        \"path\": ",out)!=EOF&&js(out,r->source_path)&&fprintf(out,",\n        \"hash_fnv1a64\": \"%016" PRIx64 "\",\n        \"length_bytes\": %zu\n      }\n    }%s\n",r->source_hash,r->source_length,final?"":",")>=0;}

static bool write_quantity(FILE* out,const FisicsPhysicalQuantityKind* q,bool final){if(fputs("    {\n      \"id\": ",out)==EOF||!js(out,q->id)||fputs(",\n      \"dimension_system\": ",out)==EOF||!js(out,q->dimension_system)||fputs(",\n      \"dimension_vector\": [",out)==EOF)return false;for(size_t i=0;i<8u;++i)if(fprintf(out,"%s%d",i?", ":"",(int)q->dimension[i])<0)return false;return fputs("],\n      \"dimension_text\": ",out)!=EOF&&js(out,q->dimension_text)&&fputs(",\n      \"origin_catalog\": ",out)!=EOF&&js(out,q->catalog_path)&&fprintf(out,"\n    }%s\n",final?"":",")>=0;}

static bool write_binding(FILE* out,const FisicsPhysicalUnitsBinding* b,bool final){if(fputs("    {\n      \"binding_id\": ",out)==EOF||!js(out,b->binding_id)||fputs(",\n      \"record_index\": ",out)==EOF)return false;if(b->has_record_index){if(fprintf(out,"%zu",b->record_index)<0)return false;}else if(fputs("null",out)==EOF)return false;if(fputs(",\n      \"symbol_stable_id\": ",out)==EOF||!nullable(out,b->symbol_stable_id)||fputs(",\n      \"symbol_name\": ",out)==EOF||!js(out,b->symbol_name)||fputs(",\n      \"source\": {\n        \"file\": ",out)==EOF||!js(out,b->source_path)||fprintf(out,",\n        \"start_line\": %d,\n        \"start_column\": %d,\n        \"end_line\": %d,\n        \"end_column\": %d\n      },\n      \"dimension\": {\n        \"text\": ",b->start_line,b->start_column,b->end_line,b->end_column)<0||!js(out,b->dimension_text)||fputs(",\n        \"vector\": [",out)==EOF)return false;for(size_t i=0;i<8u;++i)if(fprintf(out,"%s%d",i?", ":"",(int)b->dimension[i])<0)return false;if(fputs("]\n      },\n      \"unit\": ",out)==EOF)return false;if(!b->unit_name){if(fputs("null",out)==EOF)return false;}else if(fputs("{\n        \"name\": ",out)==EOF||!js(out,b->unit_name)||fputs(",\n        \"symbol\": ",out)==EOF||!js(out,b->unit_symbol)||fputs(",\n        \"family\": ",out)==EOF||!js(out,b->unit_family)||fputs(",\n        \"scale_binary64\": ",out)==EOF||!js(out,b->scale_binary64)||fputs(",\n        \"offset_binary64\": ",out)==EOF||!js(out,b->offset_binary64)||fputs("\n      }",out)==EOF)return false;return fprintf(out,"\n    }%s\n",final?"":",")>=0;}

static bool write_form(FILE* out,const FisicsPhysicalContract* c){if(fputs("{\n        \"kind\": ",out)==EOF||!js(out,c->value_form)||fputs(",\n        \"component_count\": ",out)==EOF)return false;if(c->has_component_count){if(fprintf(out,"%zu",c->component_count)<0)return false;}else if(fputs("null",out)==EOF)return false;if(fputs(",\n        \"tensor_rank\": ",out)==EOF)return false;if(c->has_tensor_rank){if(fprintf(out,"%zu",c->tensor_rank)<0)return false;}else if(fputs("null",out)==EOF)return false;if(fputs(",\n        \"tensor_shape\": [",out)==EOF)return false;for(size_t i=0;i<c->tensor_shape_count;++i)if(fprintf(out,"%s%zu",i?", ":"",c->tensor_shape[i])<0)return false;return fputs("]\n      }",out)!=EOF;}

static bool write_contract(FILE* out,const FisicsPhysicalContract* c,bool final){if(fputs("    {\n      \"contract_id\": ",out)==EOF||!js(out,c->contract_id)||fputs(",\n      \"subject\": {\n        \"kind\": ",out)==EOF||!js(out,subject_name(c->subject_kind))||fputs(",\n        \"id\": ",out)==EOF||!js(out,c->subject_id)||fputs("\n      },\n      \"quantity_kind\": ",out)==EOF||!js(out,c->quantity_kind)||fputs(",\n      \"unit_policy\": {\n        \"mode\": ",out)==EOF||!js(out,policy_name(c->unit_policy))||fputs(",\n        \"unit\": ",out)==EOF||!nullable(out,c->expected_unit)||fputs("\n      },\n      \"value_form\": ",out)==EOF||!write_form(out,c)||fputs(",\n      \"reference_semantics\": {\n        \"kind\": ",out)==EOF||!js(out,c->reference_kind)||fputs(",\n        \"reference_subject\": ",out)==EOF||!nullable(out,c->reference_subject)||fputs(",\n        \"period_binary64\": ",out)==EOF||!nullable(out,c->period_binary64)||fputs("\n      },\n      \"frame_id\": ",out)==EOF||!nullable(out,c->frame_id)||fputs(",\n      \"state\": ",out)==EOF||!js(out,state_name(c->state))||fputs(",\n      \"evidence_origin\": ",out)==EOF||!js(out,c->state==FISICS_PHYSICAL_STATE_SOURCE_COMPATIBLE?"compiler_units_attachment":c->state==FISICS_PHYSICAL_STATE_EXTERNAL_DECLARED?"catalog_declaration":"none")||fputs(",\n      \"record_index\": ",out)==EOF)return false;if(c->has_record_index){if(fprintf(out,"%zu",c->record_index)<0)return false;}else if(fputs("null",out)==EOF)return false;if(fputs(",\n      \"binding_index\": ",out)==EOF)return false;if(c->has_binding_index){if(fprintf(out,"%zu",c->binding_index)<0)return false;}else if(fputs("null",out)==EOF)return false;if(fputs(",\n      \"conversion\": ",out)==EOF)return false;if(!c->conversion_model){if(fputs("null",out)==EOF)return false;}else if(fputs("{\n        \"model\": ",out)==EOF||!js(out,c->conversion_model)||fputs(",\n        \"scale_binary64\": ",out)==EOF||!js(out,c->conversion_scale_binary64)||fputs(",\n        \"offset_binary64\": ",out)==EOF||!js(out,c->conversion_offset_binary64)||fputs("\n      }",out)==EOF)return false;return fputs(",\n      \"origin_catalog\": ",out)!=EOF&&js(out,c->catalog_path)&&fprintf(out,"\n    }%s\n",final?"":",")>=0;}

static bool write_edge(FILE* out,const FisicsPhysicalSemanticEdge* e,bool final){if(fprintf(out,"    {\n      \"source_record_index\": %zu,\n      \"kind\": ",e->source_record_index)<0||!js(out,e->kind)||fputs(",\n      \"target_id\": ",out)==EOF||!js(out,e->target_id)||fputs(",\n      \"target_contract_index\": ",out)==EOF)return false;if(e->has_target_contract_index){if(fprintf(out,"%zu",e->target_contract_index)<0)return false;}else if(fputs("null",out)==EOF)return false;return fprintf(out,"\n    }%s\n",final?"":",")>=0;}

static bool write_document(FILE* out,const FisicsPhysicalProjectGraph* g){if(fputs("{\n  \"schema\": \"fisiCs.physical_project_graph\",\n  \"schema_version\": 1,\n  \"producer\": {\n    \"name\": \"fisiCs\",\n    \"version\": \"" FISICS_VERSION "\"\n  },\n  \"project\": {\n    \"id\": ",out)==EOF||!js(out,g->project_id)||fputs(",\n    \"manifest_path\": ",out)==EOF||!js(out,g->manifest_path)||fputs("\n  },\n  \"complete\": true,\n  \"physical_acceptance\": \"not_assessed\",\n  \"dimension_system\": \"fisiCs.si_dim8.v1\",\n  \"unit_registry\": {\n    \"id\": \"fisiCs.unit_registry\",\n    \"fingerprint_fnv1a64\": ",out)==EOF)return false;char fp[17];snprintf(fp,sizeof(fp),"%016" PRIx64,g->registry_fingerprint);if(!js(out,fp)||fprintf(out,"\n  },\n  \"coverage\": {\n    \"uncovered_authored_records\": %zu,\n    \"uncovered_relationship_targets\": %zu,\n    \"source_unverified_contracts\": %zu,\n    \"external_declared_contracts\": %zu\n  },\n  \"semantic_graph_receipt\": {\n    \"path\": ",g->uncovered_record_count,g->uncovered_target_count,g->unverified_contract_count,g->external_contract_count)<0||!js(out,g->semantic_graph_path)||fputs(",\n    \"project_id\": ",out)==EOF||!js(out,g->semantic_project_id)||fputs("\n  },\n  \"source_receipts\": [\n",out)==EOF)return false;for(size_t i=0;i<g->receipt_count;++i)if(!write_receipt(out,&g->receipts[i],i+1u==g->receipt_count))return false;if(fputs("  ],\n  \"quantity_kinds\": [\n",out)==EOF)return false;for(size_t i=0;i<g->quantity_kind_count;++i)if(!write_quantity(out,&g->quantity_kinds[i],i+1u==g->quantity_kind_count))return false;if(fputs("  ],\n  \"units_bindings\": [\n",out)==EOF)return false;for(size_t i=0;i<g->binding_count;++i)if(!write_binding(out,&g->bindings[i],i+1u==g->binding_count))return false;if(fputs("  ],\n  \"physical_contracts\": [\n",out)==EOF)return false;for(size_t i=0;i<g->contract_count;++i)if(!write_contract(out,&g->contracts[i],i+1u==g->contract_count))return false;if(fputs("  ],\n  \"semantic_edges\": [\n",out)==EOF)return false;for(size_t i=0;i<g->semantic_edge_count;++i)if(!write_edge(out,&g->semantic_edges[i],i+1u==g->semantic_edge_count))return false;if(fputs("  ],\n  \"unbound_units_evidence\": [",out)==EOF)return false;bool first=true;for(size_t i=0;i<g->binding_count;++i)if(!g->bindings[i].has_record_index){if(fprintf(out,"%s%zu",first?"":", ",i)<0)return false;first=false;}return fputs("]\n}\n",out)!=EOF;}

static char* canonical_output(const char* path){char* existing=realpath(path,NULL);if(existing)return existing;const char* slash=strrchr(path,'/');char* dir=NULL;const char* leaf=path;if(slash){size_t n=(size_t)(slash-path);if(n==0)dir=strdup("/");else{dir=(char*)malloc(n+1u);if(dir){memcpy(dir,path,n);dir[n]='\0';}}leaf=slash+1;}else dir=strdup(".");if(!dir||!leaf[0]){free(dir);return NULL;}char* base=realpath(dir,NULL);free(dir);if(!base)return NULL;size_t n=strlen(base)+strlen(leaf)+2u;char* out=(char*)malloc(n);if(out)snprintf(out,n,"%s%s%s",base,strcmp(base,"/")==0?"":"/",leaf);free(base);return out;}

bool fisics_physical_project_graph_write_json_atomic(const char* output_path,const FisicsPhysicalProjectManifest* manifest,const FisicsPhysicalProjectGraph* graph,FisicsSemanticProjectDiagnostic* d){if(!output_path||!output_path[0]||!manifest||!graph){diag(d,"invalid physical graph publication arguments");return false;}char* output=canonical_output(output_path);if(!output){diag(d,"cannot resolve physical graph output path: %s",output_path);return false;}bool conflict=!strcmp(output,manifest->manifest_path)||!strcmp(output,manifest->semantic_graph_path);for(size_t i=0;!conflict&&i<manifest->units_metadata_path_count;++i)conflict=!strcmp(output,manifest->units_metadata_paths[i]);for(size_t i=0;!conflict&&i<manifest->catalog_path_count;++i)conflict=!strcmp(output,manifest->catalog_paths[i]);for(size_t i=0;!conflict&&i<graph->receipt_count;++i)conflict=!strcmp(output,graph->receipts[i].source_path);if(conflict){diag(d,"physical graph output conflicts with an input or source path: %s",output);free(output);return false;}size_t n=strlen(output);char* temp=(char*)malloc(n+sizeof(".tmp.XXXXXX"));if(!temp){free(output);diag(d,"out of memory creating physical graph output");return false;}snprintf(temp,n+sizeof(".tmp.XXXXXX"),"%s.tmp.XXXXXX",output);int fd=mkstemp(temp);if(fd<0){diag(d,"failed to create physical graph temporary output: %s",output);free(temp);free(output);return false;}FILE* out=fdopen(fd,"w");bool ok=out&&write_document(out,graph);if(getenv("FISICS_TEST_FAIL_PHYSICAL_PROJECT_GRAPH_WRITE"))ok=false;if(out){if(ok&&fflush(out)!=0)ok=false;if(ok&&fsync(fd)!=0)ok=false;if(fclose(out)!=0)ok=false;}else close(fd);if(ok&&rename(temp,output)!=0)ok=false;if(!ok){unlink(temp);diag(d,"failed to atomically publish physical project graph: %s",output);}free(temp);free(output);return ok;}
